CREATE TABLE meta (id INTEGER PRIMARY KEY CHECK(id=1), company_id TEXT NOT NULL, company_name TEXT NOT NULL, epoch TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>=0), currency TEXT NOT NULL CHECK(currency='VND'), regime TEXT NOT NULL) STRICT;
CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','accountant','viewer')), password_hash TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1))) STRICT;
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL) STRICT;
CREATE TABLE login_limits (username TEXT PRIMARY KEY, failures INTEGER NOT NULL, blocked_until TEXT NOT NULL) STRICT;
CREATE TABLE periods (period TEXT PRIMARY KEY CHECK(length(period)=7), closed INTEGER NOT NULL CHECK(closed IN (0,1))) STRICT;
CREATE TABLE accounts (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, account_group TEXT NOT NULL, requires_partner INTEGER NOT NULL CHECK(requires_partner IN (0,1)), active INTEGER NOT NULL CHECK(active IN (0,1))) STRICT;
CREATE TABLE partners (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('customer','supplier','both')), email TEXT NOT NULL, phone TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1))) STRICT;
CREATE TABLE documents (id TEXT PRIMARY KEY, reference TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('receipt','payment','sale','purchase','journal')), date TEXT NOT NULL CHECK(length(date)=10), description TEXT NOT NULL, partner_id TEXT REFERENCES partners(id), status TEXT NOT NULL CHECK(status IN ('draft','posted')), version INTEGER NOT NULL CHECK(version>0), source_type TEXT NOT NULL, source_id TEXT NOT NULL, reversal_of TEXT REFERENCES documents(id), policy_id TEXT, posted_at TEXT, posted_order INTEGER, UNIQUE(source_type,source_id), UNIQUE(reversal_of)) STRICT;
CREATE UNIQUE INDEX documents_reference ON documents(reference) WHERE status='posted';
CREATE UNIQUE INDEX documents_posted_order ON documents(posted_order) WHERE posted_order IS NOT NULL;
CREATE INDEX documents_period ON documents(date,status);
CREATE TABLE document_lines (document_id TEXT NOT NULL REFERENCES documents(id), position INTEGER NOT NULL CHECK(position>=0), account_id TEXT NOT NULL REFERENCES accounts(id), partner_id TEXT REFERENCES partners(id), partner_name TEXT NOT NULL, account_name TEXT NOT NULL, description TEXT NOT NULL, debit INTEGER NOT NULL CHECK(debit>=0), credit INTEGER NOT NULL CHECK(credit>=0), CHECK(NOT(debit>0 AND credit>0)), PRIMARY KEY(document_id,position)) STRICT;
CREATE INDEX lines_account ON document_lines(account_id,document_id);
CREATE INDEX lines_partner ON document_lines(partner_id,account_id);
CREATE TABLE counters (scope TEXT PRIMARY KEY, value INTEGER NOT NULL CHECK(value>0)) STRICT;
CREATE TABLE commands (actor_id TEXT NOT NULL REFERENCES users(id), operation TEXT NOT NULL, key TEXT NOT NULL, payload_hash TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)), created_at TEXT NOT NULL, PRIMARY KEY(actor_id,operation,key)) STRICT;
CREATE TABLE audit (id INTEGER PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, occurred_at TEXT NOT NULL, revision INTEGER NOT NULL) STRICT;
CREATE TABLE policies (id TEXT PRIMARY KEY, version INTEGER NOT NULL UNIQUE CHECK(version>0), effective_from TEXT NOT NULL UNIQUE, data TEXT NOT NULL CHECK(json_valid(data))) STRICT;
CREATE TABLE items (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, unit TEXT NOT NULL, tracked INTEGER NOT NULL CHECK(tracked IN (0,1)), active INTEGER NOT NULL CHECK(active IN (0,1))) STRICT;
CREATE TABLE stock_lots (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES items(id), document_id TEXT NOT NULL REFERENCES documents(id) DEFERRABLE INITIALLY DEFERRED, date TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>=0), value INTEGER NOT NULL CHECK(value>=0), scale INTEGER NOT NULL CHECK(scale BETWEEN 0 AND 6)) STRICT;
CREATE TABLE stock_movements (id INTEGER PRIMARY KEY, item_id TEXT NOT NULL REFERENCES items(id), document_id TEXT NOT NULL REFERENCES documents(id) DEFERRABLE INITIALLY DEFERRED, date TEXT NOT NULL, quantity INTEGER NOT NULL, value INTEGER NOT NULL, scale INTEGER NOT NULL CHECK(scale BETWEEN 0 AND 6)) STRICT;
CREATE INDEX stock_movement_item ON stock_movements(item_id,date);
CREATE TABLE employees (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, base_salary INTEGER NOT NULL CHECK(base_salary>=0), insurance_base INTEGER NOT NULL CHECK(insurance_base>=0), dependents INTEGER NOT NULL CHECK(dependents BETWEEN 0 AND 100), active INTEGER NOT NULL CHECK(active IN (0,1))) STRICT;
CREATE TABLE assets (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('fixed','prepaid')), cost INTEGER NOT NULL CHECK(cost>0), residual INTEGER NOT NULL CHECK(residual>=0 AND residual<cost), months INTEGER NOT NULL CHECK(months BETWEEN 1 AND 1200), start_period TEXT NOT NULL, recognized_document TEXT NOT NULL REFERENCES documents(id), allocated INTEGER NOT NULL CHECK(allocated>=0 AND allocated<=cost-residual)) STRICT;
CREATE TABLE operations (id TEXT PRIMARY KEY, kind TEXT NOT NULL, source_id TEXT NOT NULL, date TEXT NOT NULL, document_id TEXT NOT NULL UNIQUE REFERENCES documents(id), policy_id TEXT NOT NULL REFERENCES policies(id), payload TEXT NOT NULL CHECK(json_valid(payload)), calculation TEXT NOT NULL CHECK(json_valid(calculation)), UNIQUE(kind,source_id)) STRICT;
CREATE TABLE attachments (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), hash TEXT NOT NULL, name TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0)) STRICT;
CREATE TRIGGER posted_document_update BEFORE UPDATE ON documents WHEN OLD.status='posted' BEGIN SELECT RAISE(ABORT,'posted document is immutable'); END;
CREATE TRIGGER posted_document_delete BEFORE DELETE ON documents WHEN OLD.status='posted' BEGIN SELECT RAISE(ABORT,'posted document is immutable'); END;
CREATE TRIGGER posted_line_update BEFORE UPDATE ON document_lines WHEN (SELECT status FROM documents WHERE id=OLD.document_id)='posted' BEGIN SELECT RAISE(ABORT,'posted lines are immutable'); END;
CREATE TRIGGER posted_line_delete BEFORE DELETE ON document_lines WHEN (SELECT status FROM documents WHERE id=OLD.document_id)='posted' BEGIN SELECT RAISE(ABORT,'posted lines are immutable'); END;
CREATE TRIGGER posted_line_insert BEFORE INSERT ON document_lines WHEN (SELECT status FROM documents WHERE id=NEW.document_id)='posted' BEGIN SELECT RAISE(ABORT,'posted lines are immutable'); END;
CREATE TRIGGER document_posting BEFORE UPDATE OF status ON documents WHEN NEW.status='posted' BEGIN
 SELECT CASE WHEN (SELECT COUNT(*) FROM document_lines WHERE document_id=NEW.id)<2 THEN RAISE(ABORT,'entry needs two lines') END;
 SELECT CASE WHEN (SELECT COALESCE(SUM(debit),0) FROM document_lines WHERE document_id=NEW.id)!=(SELECT COALESCE(SUM(credit),0) FROM document_lines WHERE document_id=NEW.id) THEN RAISE(ABORT,'entry is unbalanced') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM periods WHERE period=substr(NEW.date,1,7) AND closed=0) THEN RAISE(ABORT,'period is not open') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM document_lines l JOIN accounts a ON a.id=l.account_id LEFT JOIN partners p ON p.id=l.partner_id WHERE l.document_id=NEW.id AND (a.active=0 OR l.debit+l.credit=0 OR (a.requires_partner=1 AND (p.id IS NULL OR p.active=0)))) THEN RAISE(ABORT,'invalid account or partner') END;
END;
